```mermaid
flowchart LR
  CE["Concrete<br/>Experience<br/><span style='font-size:0.9em'>(doing / having an experience)</span>"]
  RO["Reflective<br/>Observation<br/><span style='font-size:0.9em'>(reviewing / reflecting on<br/>the experience)</span>"]
  AC["Abstract<br/>Conceptualization<br/><span style='font-size:0.9em'>(making meaning / learning<br/>from the experience)</span>"]
  AE["Active<br/>Experimentation<br/><span style='font-size:0.9em'>(planning / trying out what<br/>you have learned)</span>"]

  CE --> RO
  RO --> AC
  AC --> AE
  AE --> CE

  TL["Transformation Line"]
  RO --- TL
  TL --- AC

  classDef stage fill:#0B3A66,stroke:#0B3A66,color:#ffffff,rx:14,ry:14;
  classDef tl fill:#6E8B3D,stroke:#6E8B3D,color:#ffffff,rx:4,ry:4;

  class CE,RO,AC,AE stage;
  class TL tl;

  linkStyle 0,1,2,3 stroke:#6E8B3D,stroke-width:2px;
  linkStyle 4,5 stroke:#6E8B3D,stroke-width:2px,stroke-dasharray:6 6;
```

```mermaid
flowchart TB
  %% Learning Styles of Children - Quadrant Diagram

  T["What is your child's learning style?"]
  S["Children learn best when teaching methods and educational activities match their preferred learning style(s)."]

  subgraph Q[""]
    direction LR

    subgraph L[""]
      direction TB
      V["Visual<br/><br/>Process information best when presented with charts and diagrams or purposeful symbols to help remember information."]
      RW["Reading &amp; Writing<br/><br/>Best learns when taking in new information in written form. Books, articles, notes and reading online. Taking and copying notes helps them retain information."]
    end

    subgraph R[""]
      direction TB
      A["Auditory<br/><br/>Best process information presented vocally. Group discussions and reading their work aloud help them remember information."]
      K["Kinesthetic<br/><br/>Hands-on learners who need to be physically active in the learning process. Highly active and need multi-sensory learning experiences to retain new information."]
    end
  end

  F["Most kids are able to learn using more than one learning style and are considered multi-modal learners."]

  T --> S --> Q --> F

  classDef visual fill:#e7c4d7,stroke:#caa0b6,stroke-width:1px,color:#2b2b2b;
  classDef auditory fill:#d7d8e3,stroke:#b9bbca,stroke-width:1px,color:#2b2b2b;
  classDef reading fill:#cfe6ea,stroke:#a9c9ce,stroke-width:1px,color:#2b2b2b;
  classDef kinesthetic fill:#cfe8dd,stroke:#a7cdbd,stroke-width:1px,color:#2b2b2b;
  classDef header fill:#ffffff,stroke:#ffffff,color:#2b2b2b;

  class T,S,F header;
  class V visual;
  class A auditory;
  class RW reading;
  class K kinesthetic;

  style Q fill:#ffffff,stroke:#ffffff;
  style L fill:#ffffff,stroke:#ffffff;
  style R fill:#ffffff,stroke:#ffffff;
```

